<?php
declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';$id=requestId();$m=$_SERVER['REQUEST_METHOD']??'GET';
try{$model=ModelFactory::users();switch($m){case 'GET':$r=$model->GetUser($id);if(!$r)apiResponse(404,['success'=>false,'message'=>'User not found.']);apiResponse(200,['success'=>true,'data'=>$r]);case 'PUT':case 'PATCH':$d=requestData();if(!$model->UpdateUser($id,(string)($d['fullName']??''),(string)($d['username']??''),(string)($d['email']??''),isset($d['password'])?(string)$d['password']:null))apiResponse(404,['success'=>false,'message'=>'User not found.']);apiResponse(200,['success'=>true,'message'=>'User updated.','data'=>$model->GetUser($id)]);case 'DELETE':if(!$model->DeleteUser($id))apiResponse(404,['success'=>false,'message'=>'User not found.']);apiResponse(200,['success'=>true,'message'=>'User deleted.']);default:header('Allow: GET, PUT, PATCH, DELETE');apiResponse(405,['success'=>false,'message'=>'Method not allowed.']);}}catch(Throwable $e){handleError($e);}
